def load_strategyqa(path: str, n_problems: int | None = None) -> list[dict]:
    with open(path) as f:
        data = json.load(f)
    for p in data:
        p.setdefault("dataset", "strategyqa")
    if n_problems is not None:
        data = data[:n_problems]
    return data


def extract_yesno_answer(text: str) -> str:
    text_lower = text.strip().lower()
    if text_lower == "true":
        return "Yes"
    if text_lower == "false":
        return "No"
    for pattern in [
        r'the\s+answer\s+is\s*[:\s]*(yes|no|true|false)',
        r'answer\s*[:\s]*(yes|no|true|false)',
        r'\\boxed\{(yes|no|true|false)\}',
    ]:
        match = re.search(pattern, text_lower)
        if match:
            v = match.group(1)
            return "Yes" if v in ("yes", "true") else "No"
    if text_lower.endswith("yes") or text_lower.startswith("yes"):
        return "Yes"
    if text_lower.endswith("no") or text_lower.startswith("no"):
        return "No"
    if "true" in text_lower:
        return "Yes"
    if "false" in text_lower:
        return "No"
    yes_count = len(re.findall(r'\byes\b', text_lower))
    no_count = len(re.findall(r'\bno\b', text_lower))
    if yes_count > no_count:
        return "Yes"
    if no_count > yes_count:
        return "No"
    return ""


